namespace NuExt.Minimal.Mvvm.SourceGenerator.Tests;

internal static class LocalizeAttributes
{
    public static List<(string source, string? expected)> Sources =
    [
        (
            source :
            """
            using Minimal.Mvvm;

            [Localize("local.en-US.json")]
            public static partial class MyLoc
            {
            }
            """,
            expected :
            """
            // <auto-generated>
            //     Auto-generated by [GeneratorName] [GeneratorVersion]
            // </auto-generated>

            #nullable enable

            partial class MyLoc
            {
                /// <summary>
                /// Looks up a localized string similar to An error has occurred in {0}:{1}.
                /// </summary>
                public static string An_error_has_occurred_in_Arg1_Arg2 { get; set; } = "An error has occurred in {0}:{1}";

                /// <summary>
                /// Looks up a localized string similar to My Description.
                /// </summary>
                public static string Description { get; set; } = "My Description";

                /// <summary>
                /// Looks up a localized string similar to This &amp; that &lt; those &gt; "these" 'others' \ here and there\r\n\\.
                /// </summary>
                public static string Escaped { get; set; } = "This & that < those > \"these\" 'others' \\ here and there\r\n\\\\";

                /// <summary>
                /// Looks up a localized string similar to My Name.
                /// </summary>
                public static string Name { get; set; } = "My Name";

                public static class Application
                {
                    /// <summary>
                    /// Looks up a localized string similar to Sample application.
                    /// </summary>
                    public static string Title { get; set; } = "Sample application";
                
                    public static class Messages
                    {
                        /// <summary>
                        /// Looks up a localized string similar to Do you really want to exit?.
                        /// </summary>
                        public static string ExitConfirmation { get; set; } = "Do you really want to exit?";
                    }
                }

                /// <summary>
                /// Loads localized strings from the specified JSON file.
                /// </summary>
                /// <param name="fileName">The localization JSON file name.</param>
                public static void LoadFromJsonFile(string fileName)
                {
                    _ = fileName ?? throw new global::System.ArgumentNullException(nameof(fileName));
                    using var stream = global::System.IO.File.OpenRead(fileName);
                    using var document = global::System.Text.Json.JsonDocument.Parse(stream);
                    if (document.RootElement.ValueKind != global::System.Text.Json.JsonValueKind.Object)
                    {
                        throw new global::System.IO.InvalidDataException("The localization file must contain a JSON object.");
                    }
                    LoadFromJsonElement(document.RootElement, path: null);

                    return;

                    void LoadFromJsonElement(global::System.Text.Json.JsonElement element, string? path)
                    {
                        foreach (var property in element.EnumerateObject())
                        {
                            var propertyPath = string.IsNullOrEmpty(path) ? property.Name : $"{path}.{property.Name}";
                            switch (property.Value.ValueKind)
                            {
                                case global::System.Text.Json.JsonValueKind.String:
                                    SetLocalizedString(propertyPath, property.Value.GetString()!);
                                    break;
                                case global::System.Text.Json.JsonValueKind.Object:
                                    LoadFromJsonElement(property.Value, propertyPath);
                                    break;
                                default:
                                    throw new global::System.IO.InvalidDataException($"Localization entry '{propertyPath}' must be a string or an object.");
                            }
                        }
                    }

                    void SetLocalizedString(string path, string value)
                    {
                        switch (path)
                        {
                            case "An error has occurred in Arg1:Arg2":
                                An_error_has_occurred_in_Arg1_Arg2 = value;
                                break;
                            case "Description":
                                Description = value;
                                break;
                            case "Escaped":
                                Escaped = value;
                                break;
                            case "Name":
                                Name = value;
                                break;
                            case "Application.Title":
                                Application.Title = value;
                                break;
                            case "Application.Messages.ExitConfirmation":
                                Application.Messages.ExitConfirmation = value;
                                break;
                            default:
                                break;
                        }
                    }
                }
            }
            """ ),
    ];
}
